//     complexity (and non-determinism) without any benefit.
//  3. Moved currency and locale validation to the top of FormatLedger.
//     The old code validated the currency only per entry, and for an
//     empty ledger it made a recursive call with a dummy entry solely to
//     trigger that validation. Validating up front covers both cases.
//  4. Collapsed the duplicated per-locale formatting branches into a
//     localeConfig table, with small helpers for the date, description,
//     and amount columns.
//  5. Replaced the opaque errors.New("") values with descriptive errors.
package ledger

import (
	"fmt"
	"sort"
	"strconv"
	"strings"
	"unicode/utf8"
)

// Entry is a single ledger entry.
type Entry struct {
	Date        string // "Y-m-d"
	Description string
	Change      int // in cents
}

// Column widths of the printed table.
const (
	dateColumnWidth        = 10
	descriptionColumnWidth = 25
	changeColumnWidth      = 13
)

// localeConfig captures everything that varies between the supported locales.
type localeConfig struct {
	dateColumn        string
	descriptionColumn string
	changeColumn      string
	formatDate        func(year, month, day string) string
	formatAmount      func(symbol string, cents int) string
}

var localeConfigs = map[string]localeConfig{
	"en-US": {
		dateColumn:        "Date",
		descriptionColumn: "Description",
		changeColumn:      "Change",
		formatDate: func(year, month, day string) string {
			return month + "/" + day + "/" + year
		},
		formatAmount: func(symbol string, cents int) string {
			amount := symbol + formatNumber(cents, ",", ".")
			if cents < 0 {
				return "(" + amount + ")"
			}
			return amount + " "
		},
	},
	"nl-NL": {
		dateColumn:        "Datum",
		descriptionColumn: "Omschrijving",
		changeColumn:      "Verandering",
		formatDate: func(year, month, day string) string {
			return day + "-" + month + "-" + year
		},
		formatAmount: func(symbol string, cents int) string {
			amount := symbol + " " + formatNumber(cents, ".", ",")
			if cents < 0 {
				return amount + "-"
			}
			return amount + " "
		},
	},
}

// currencySymbols maps a currency code to its symbol.
var currencySymbols = map[string]string{
	"USD": "$",
	"EUR": "€",
}

// FormatLedger renders entries as a formatted ledger table for the given
// locale and currency. Entries are printed sorted by date, then
// description, then change. The input slice is not modified.
func FormatLedger(currency, locale string, entries []Entry) (string, error) {
	symbol, ok := currencySymbols[currency]
	if !ok {
		return "", fmt.Errorf("unsupported currency %q", currency)
	}
	cfg, ok := localeConfigs[locale]
	if !ok {
		return "", fmt.Errorf("unsupported locale %q", locale)
	}

	sorted := make([]Entry, len(entries))
	copy(sorted, entries)
	sort.Slice(sorted, func(i, j int) bool {
		if sorted[i].Date != sorted[j].Date {
			return sorted[i].Date < sorted[j].Date
		}
		if sorted[i].Description != sorted[j].Description {
			return sorted[i].Description < sorted[j].Description
		}
		return sorted[i].Change < sorted[j].Change
	})

	var b strings.Builder
	b.WriteString(fmt.Sprintf("%-*s | %-*s | %s\n",
		dateColumnWidth, cfg.dateColumn,
		descriptionColumnWidth, cfg.descriptionColumn,
		cfg.changeColumn))
	for _, entry := range sorted {
		line, err := formatLine(cfg, symbol, entry)
		if err != nil {
			return "", err
		}
		b.WriteString(line)
	}
	return b.String(), nil
}

// formatLine renders a single row of the ledger table.
func formatLine(cfg localeConfig, symbol string, entry Entry) (string, error) {
	year, month, day, err := splitDate(entry.Date)
	if err != nil {
		return "", err
	}
	amount := cfg.formatAmount(symbol, entry.Change)
	// The amount column is padded to its width by rune count, so that
	// multi-byte symbols such as "€" line up correctly.
	pad := strings.Repeat(" ", changeColumnWidth-utf8.RuneCountInString(amount))
	return fmt.Sprintf("%s | %s | %s%s\n",
		cfg.formatDate(year, month, day), formatDescription(entry.Description), pad, amount)
}

// splitDate validates a "YYYY-MM-DD" date and returns its parts.
func splitDate(date string) (year, month, day string, err error) {
	if len(date) != 10 || date[4] != '-' || date[7] != '-' {
		return "", "", "", fmt.Errorf("invalid date %q, expected format YYYY-MM-DD", date)
	}
	return date[0:4], date[5:7], date[8:10], nil
}

// formatDescription fits a description into the description column,
// truncating overlong values with an ellipsis.
func formatDescription(description string) string {
	if len(description) > descriptionColumnWidth {
		return description[:descriptionColumnWidth-3] + "..."
	}
	return description + strings.Repeat(" ", descriptionColumnWidth-len(description))
}

// formatNumber renders the absolute value of a cent amount with the given
// thousands and decimal separators, e.g. 12345 with "." and "," becomes
// "123,45".
func formatNumber(cents int, thousandsSep, decimalSep string) string {
	if cents < 0 {
		cents = -cents
	}
	digits := strconv.Itoa(cents)
	for len(digits) < 3 {
		digits = "0" + digits
	}
	whole, fraction := digits[:len(digits)-2], digits[len(digits)-2:]
	return groupDigits(whole, thousandsSep) + decimalSep + fraction
}

// groupDigits inserts a separator every three digits from the right,
// e.g. groupDigits("123456", ",") == "123,456".
func groupDigits(digits, sep string) string {
	var b strings.Builder
	for i, r := range digits {
		if i > 0 && (len(digits)-i)%3 == 0 {
			b.WriteString(sep)
		}
		b.WriteRune(r)
	}
	return b.String()
}
"}

